 function draw(focus){const selected=E.filter(songs,state);panel.innerHTML=timelineExplorerMarkup(state,expanded,limit);$('#ce-count').textContent=selected.length+' / '+songs.length+' 掲載作品';$('#timeline-region').value=state.region||'';if(document.activeElement!==$('#timeline-search'))$('#timeline-search').value=state.q||'';view.querySelectorAll('[data-timeline-decade]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.timelineDecade===(state.decade||''))));$('#timeline-count').textContent=selected.length+' / '+songs.length+' RECORDS';const restricted=Object.keys(state).some(k=>!['decade','year'].includes(k));$('#timeline-chart').innerHTML=window.CrateChronology(selected,esc,{events:(window.CRATE_EVENTS||[]).filter(e=>(!state.decade||String(Math.floor(e.year/10)*10)===state.decade)&&(!state.year||String(e.year)===state.year)&&(!restricted||selected.some(s=>s.year===e.year)))});linkRoutes(panel);linkRoutes($('#timeline-chart'));if(focus){const target=[...panel.querySelectorAll('button')].find(b=>Object.entries(focus).every(([k,v])=>b.dataset[k]===v))||panel.querySelector('[data-ce-reset]')||$('#ce-count');target.setAttribute('tabindex',target.tagName==='BUTTON'?'0':'-1');target.focus({preventScroll:true})}}
 function commit(next,focus,replace=false){state=E.parse(E.serialize(next));limit=12;const q=E.serialize(state),value='#/timeline'+(q?'?'+q:'');const url=new URL(routeURL(value),location.origin),old=new URL(location.href);for(const k of campaignKeys)if(old.searchParams.has(k))url.searchParams.set(k,old.searchParams.get(k));history[replace?'replaceState':'pushState']({...history.state,crateRoute:value},'',url.pathname+url.search);draw(focus);updateMetadata(value);addPageSharing(value);}
 panel.onclick=e=>{const b=e.target.closest('button');if(e.target.closest('[data-ce-jump]')){e.preventDefault();$('#timeline-reading').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#timeline-reading').focus({preventScroll:true});return}if(!b)return;const next={...state};if(b.hasAttribute('data-ce-key')){next[b.dataset.ceKey]=b.dataset.ceValue;if(b.dataset.ceKey==='decade')delete next.year;commit(next,{ceKey:b.dataset.ceKey,ceValue:b.dataset.ceValue})}else if(b.hasAttribute('data-ce-type')){if(b.dataset.ceType)next.type=b.dataset.ceType;else delete next.type;commit(next,{ceType:b.dataset.ceType})}else if(b.hasAttribute('data-ce-remove')){delete next[b.dataset.ceRemove];if(b.dataset.ceRemove==='decade')delete next.year;commit(next,{ceRemove:b.dataset.ceRemove})}else if(b.hasAttribute('data-ce-reset'))commit({}, {ceType:''});else if(b.hasAttribute('data-ce-expand')){if(expanded.has(b.dataset.ceExpand))expanded.delete(b.dataset.ceExpand);else expanded.add(b.dataset.ceExpand);draw();panel.querySelector('#ce-title-'+b.dataset.ceExpand)?.scrollIntoView({block:'nearest'});const first=panel.querySelector('[data-ce-key="'+b.dataset.ceExpand+'"]');first?.focus({preventScroll:true})}else if(b.hasAttribute('data-ce-more')){const firstNew=limit;limit+=24;draw();panel.querySelectorAll('.ce-results li a')[firstNew]?.focus()}};
