function featureGrid(type){const active=eligibleFeatures().filter(f=>f.type===type),archive=publishedFeatures().filter(f=>f.type===type&&f.qualification.tier==='archive');const grid=xs=>'<div class="feature-grid feature-swipe" role="region" aria-label="特集カード一覧" tabindex="0">'+xs.map(featureCard).join('')+'</div>';return '<p class="feature-policy">'+esc(featurePolicy)+'</p><p class="feature-swipe-hint">左右にスワイプして特集を探す →</p>'+grid(active)+(archive.length?'<section class="feature-archive"><h2>ARCHIVE</h2><p>掲載曲数にかかわらず、公開済みの特集を残しています。</p>'+grid(archive)+'</section>':'')}
