function featurePersonal(f){const p=f.personalFeature;if(!p)return '';const links=xs=>'<ul>'+xs.map(x=>'<li><a href="'+esc(x.trackId?'#/song/'+x.trackId:x.url)+'"'+(x.trackId?'':' target="_blank" rel="noopener noreferrer"')+'>'+esc(x.label)+(x.trackId?' ▶':' ↗')+'</a></li>').join('')+'</ul>';return '<section class="feature-personal" aria-label="DJ Naoyamanの体験"><p class="eyebrow">MY EXPERIENCE</p><h2>'+esc(p.title)+'</h2><p class="feature-personal-byline">'+esc(p.byline)+'</p>'+p.paragraphs.map(x=>'<p>'+esc(x)+'</p>').join('')+links(p.references)+'<div class="feature-photo-grid">'+p.photos.map(x=>'<figure><img src="'+origin+'/'+esc(x.image)+'" width="'+x.width+'" height="'+x.height+'" alt="'+esc(x.alt)+'" loading="lazy" decoding="async"><figcaption>'+esc(x.caption)+'</figcaption></figure>').join('')+'</div><p>'+esc(p.eventNote)+'</p>'+links(p.eventSources)+'</section>'}
function featureEssay(f){const e=f.editorial;if(e.format==='source-led-v1')return featureLongform(e);return '<article class="prose feature-editorial"><p class="eyebrow">DJ NAOYAMAN’S VIEW</p><h2>'+esc(e.title)+'</h2><h3>音楽性と背景</h3><p>'+esc(e.context)+'</p><h3>後世に残したもの</h3><p>'+esc(e.legacy)+'</p><h3>私の聴き方</h3><p>'+esc(e.listening)+'</p>'+(e.connections?'<h3>作品と系譜をたどる</h3><p>'+esc(e.connections)+'</p>':'')+'<p class="read-only-note">影響の評価と聴き方はDJ Naoyamanの考察です。音楽性と背景の参考資料は以下に掲載しています。</p><h3>参考資料</h3><ul>'+e.sources.map(s=>'<li><a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.label)+' ↗</a></li>').join('')+'</ul></article>'}
function featureInline(text){let out='',offset=0;const re=/\[([^\]\n]+)\]\(([^\s)]+)\)/g;for(const m of text.matchAll(re)){out+=esc(text.slice(offset,m.index));const url=m[2];if(!/^#\/song\/[a-z0-9-]+$/.test(url)&&!url.startsWith('https://'))throw new Error('Invalid feature link');out+='<a href="'+esc(url)+'">'+esc(m[1])+'</a>';offset=m.index+m[0].length}return out+esc(text.slice(offset))}
function featureLongform(e){if(!Array.isArray(e.sources)||e.sources.some(s=>!s||typeof s.label!=='string'||!s.label.trim()||typeof s.url!=='string'||!/^https:\/\/[^/\s]+/.test(s.url)))throw new Error('Invalid feature source');return '<article class="prose feature-editorial feature-editorial--source-led"><p class="eyebrow">PRODUCTION STORIES</p><h2>'+esc(e.title)+'</h2><p class="intro">'+esc(e.deck)+'</p>'+e.introduction.map(p=>'<p>'+featureInline(p)+'</p>').join('')+e.sections.map(s=>{const refs=s.sources||[];if(new Set(refs).size!==refs.length||refs.some(i=>!Number.isInteger(i)||!e.sources[i]))throw new Error('Invalid feature citation');return '<section><h3>'+esc(s.heading)+'</h3>'+s.paragraphs.map(p=>'<p>'+featureInline(p)+'</p>').join('')+(refs.length?'<p class="essay-references">出典：'+refs.map(i=>'<a href="'+esc(e.sources[i].url)+'">'+esc(e.sources[i].label)+'</a>').join(' / ')+'</p>':'')+'</section>'}).join('')+'<p class="read-only-note">'+esc(e.disclosure)+'</p></article>'}
